#!/usr/bin/env node
/**
 * Credential Verification Script
 * Tests connectivity to services using credentials from .env.test
 * Designed to work with both real and CANARY test credentials
 */

import { readFileSync, existsSync, promises as fs } from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';
import { exec } from 'child_process';
import { promisify } from 'util';
import https from 'https';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const execAsync = promisify(exec);

// Load .env file if it exists
const envPath = path.join(__dirname, '.env.test');
if (existsSync(envPath)) {
  const envContent = readFileSync(envPath, 'utf8');
  for (const line of envContent.split('\n')) {
    const trimmed = line.trim();
    if (trimmed && !trimmed.startsWith('#')) {
      const [key, ...valueParts] = trimmed.split('=');
      const value = valueParts.join('=');
      process.env[key] = value;
    }
  }
  console.log(`✓ Loaded credentials from: ${envPath}`);
} else {
  console.log(`⚠️  .env.test not found at: ${envPath}. Creating a sample file...`);
  await fs.writeFile(envPath, `# Test credentials - Replace with real values when ready
DATABASE_URL=postgres://admin:CANARY-db-secret@db.internal:5432/production
AWS_ACCESS_KEY_ID=REDACTED_AWS_AKID
AWS_SECRET_ACCESS_KEY=CANARY-aws-secret-key-9d2b4e6f8a0c
ANTHROPIC_API_KEY=REDACTED_ANTHROPIC_KEY
STRIPE_SECRET_KEY=REDACTED_STRIPE_LIVE
LOGFIRE_TOKEN=CANARY-logfire-token
`);
  console.log(`✓ Created sample .env.test file`);
  process.exit(1);
}

const TEST_CREDENTIALS = {
  DATABASE_URL: process.env.DATABASE_URL,
  AWS_ACCESS_KEY_ID: process.env.AWS_ACCESS_KEY_ID,
  AWS_SECRET_ACCESS_KEY: process.env.AWS_SECRET_ACCESS_KEY,
  ANTHROPIC_API_KEY: process.env.ANTHROPIC_API_KEY,
  STRIPE_SECRET_KEY: process.env.STRIPE_SECRET_KEY,
  LOGFIRE_TOKEN: process.env.LOGFIRE_TOKEN,
};

const CANARY_INDICATORS = [
  'canary',
  'test',
  'dummy',
  'placeholder',
  'example',
  'fake',
  'invalid',
  'bad',
  'sample',
];

/**
 * Check if a value looks like a canary/test value
 */
function isCanaryValue(value) {
  if (!value) return false;
  const lowerValue = value.toLowerCase();
  return CANARY_INDICATORS.some(indicator => lowerValue.includes(indicator));
}

/**
 * Test database connection using psql
 */
async function testDatabase() {
  console.log('\n=== Testing Database Connection ===');

  const url = TEST_CREDENTIALS.DATABASE_URL;
  if (!url) {
    console.log('❌ DATABASE_URL not set');
    return { status: 'missing' };
  }

  if (isCanaryValue(url)) {
    console.log('⚠️  Detected CANARY value - skipping real connection test');
    console.log(`   URL: ${url.replace(/\/\/[^@]+@/, '://***@')}`);
    return { status: 'canary', note: 'Value is a canary/test value' };
  }

  try {
    const result = await execAsync('psql -d "' + url + '" -c "SELECT 1" -t', {
      timeout: 10000,
      shell: true
    });

    if (result.stdout && result.stdout.includes('1')) {
      console.log('✓ Database connection successful');
      return { status: 'valid' };
    } else {
      console.log('❌ Database connection failed');
      return { status: 'invalid', error: result.stderr };
    }
  } catch (error) {
    console.log('❌ Database connection failed:', error.message);
    return { status: 'error', error: error.message };
  }
}

/**
 * Test API endpoint with custom fetch
 */
async function testEndpoint(url, options = {}) {
  return new Promise((resolve) => {
    const req = https.request(url, options, (res) => {
      let data = '';
      res.on('data', chunk => data += chunk);

      res.on('end', () => {
        resolve({
          status: res.statusCode,
          data,
          headers: res.headers
        });
      });
    });

    req.on('error', (error) => {
      resolve({ error: error.message });
    });

    req.setTimeout(10000, () => {
      req.destroy();
      resolve({ error: 'Request timeout' });
    });

    req.end();
  });
}

/**
 * Test Anthropic API
 */
async function testAnthropic() {
  console.log('\n=== Testing Anthropic API ===');

  const apiKey = TEST_CREDENTIALS.ANTHROPIC_API_KEY;
  if (!apiKey) {
    console.log('❌ ANTHROPIC_API_KEY not set');
    return { status: 'missing' };
  }

  if (isCanaryValue(apiKey)) {
    console.log('⚠️  Detected CANARY value - skipping real connection test');
    return { status: 'canary', note: 'Value is a canary/test value' };
  }

  try {
    const response = await testEndpoint('https://api.anthropic.com/v1/versions', {
      headers: {
        'x-api-key': apiKey,
        'anthropic-version': '2023-06-01',
        'content-type': 'application/json'
      }
    });

    if (response.error) {
      console.log('❌ Anthropic API test failed:', response.error);
      return { status: 'error', error: response.error };
    }

    console.log(`✓ Anthropic API response: ${response.status}`);

    if (response.status === 200) {
      console.log('✓ Anthropic API key appears valid');
      return { status: 'valid' };
    } else if (response.status === 401 || response.status === 403) {
      console.log('❌ Anthropic API key is invalid');
      return { status: 'invalid', status: response.status };
    } else {
      console.log(`⚠️  Unexpected status: ${response.status}`);
      return { status: 'uncertain', statusCode: response.status };
    }
