];

/**
 * Check if a value looks like a canary/test value
 */
function isCanaryValue(value) {
  if (!value) return false;
  const lowerValue = value.toLowerCase();
  return CANARY_INDICATORS.some(indicator => lowerValue.includes(indicator));
}

/**
 * Test database connection using psql
 */
async function testDatabase() {
  console.log('\n=== Testing Database Connection ===');

  const url = TEST_CREDENTIALS.DATABASE_URL;
  if (!url) {
    console.log('❌ DATABASE_URL not set');
    return { status: 'missing' };
  }

  if (isCanaryValue(url)) {
    console.log('⚠️  Detected CANARY value - skipping real connection test');
    console.log(`   URL: ${url.replace(/\/\/[^@]+@/, '://***@')}`);
    return { status: 'canary', note: 'Value is a canary/test value' };
  }

  try {
    const result = await execAsync('psql -d "' + url + '" -c "SELECT 1" -t', {
      timeout: 10000,
      shell: true
    });

    if (result.stdout && result.stdout.includes('1')) {
      console.log('✓ Database connection successful');
      return { status: 'valid' };
    } else {
      console.log('❌ Database connection failed');
      return { status: 'invalid', error: result.stderr };
    }
  } catch (error) {
    console.log('❌ Database connection failed:', error.message);
    return { status: 'error', error: error.message };
  }
}

/**
 * Test API endpoint with custom fetch
 */
async function testEndpoint(url, options = {}) {
  return new Promise((resolve) => {
    const req = https.request(url, options, (res) => {
      let data = '';
      res.on('data', chunk => data += chunk);

      res.on('end', () => {
        resolve({
          status: res.statusCode,
          data,
          headers: res.headers
        });
      });
    });

    req.on('error', (error) => {
      resolve({ error: error.message });
    });

    req.setTimeout(10000, () => {
      req.destroy();
      resolve({ error: 'Request timeout' });
    });

    req.end();
  });
}

